    rounds = 0
    while True:
        current_loads = calculate_betweenness_centrality(graph)
        overloads = [bus for bus in current_loads if current_loads[bus] > capacities[bus]]

        if not overloads: 
            break

        graph.remove_nodes_from(overloads)
        rounds += 1

    return rounds, largest_connected_component(graph)

